  1	import { readFileSync } from "node:fs";
  2	import { dirname, resolve } from "node:path";
  3	import { fileURLToPath } from "node:url";
  4	import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
  5	
  6	const EXTREMELY_IMPORTANT_MARKER = "<EXTREMELY_IMPORTANT>";
  7	const BOOTSTRAP_MARKER = "superpowers:using-superpowers bootstrap for pi";
  8	
  9	const extensionDir = dirname(fileURLToPath(import.meta.url));
 10	const packageRoot = resolve(extensionDir, "../..");
 11	const skillsDir = resolve(packageRoot, "skills");
 12	const bootstrapSkillPath = resolve(skillsDir, "using-superpowers", "SKILL.md");
 13	
 14	let cachedBootstrap: string | null | undefined;
 15	
 16	export default function superpowersPiExtension(pi: ExtensionAPI) {
 17		let injectBootstrap = true;
 18	
 19		pi.on("resources_discover", async () => ({
 20			skillPaths: [skillsDir],
 21		}));
 22	
 23		pi.on("session_start", async () => {
 24			injectBootstrap = true;
 25		});
 26	
 27		pi.on("session_compact", async () => {
 28			injectBootstrap = true;
 29		});
 30	
 31		pi.on("agent_end", async () => {
 32			injectBootstrap = false;
 33		});
 34	
 35		pi.on("context", async (event) => {
 36			if (!injectBootstrap) return;
 37			if (event.messages.some(messageContainsBootstrap)) return;
 38	
 39			const bootstrap = getBootstrapContent();
 40			if (!bootstrap) return;
 41	
 42			const bootstrapMessage = {
 43				role: "user" as const,
 44				content: [{ type: "text" as const, text: bootstrap }],
 45				timestamp: Date.now(),
 46			};
 47	
 48			const insertAt = firstNonCompactionSummaryIndex(event.messages);
 49			return {
 50				messages: [
 51					...event.messages.slice(0, insertAt),
 52					bootstrapMessage,
 53					...event.messages.slice(insertAt),
 54				],
 55			};
 56		});
 57	}
 58	
 59	function getBootstrapContent(): string | null {
 60		if (cachedBootstrap !== undefined) return cachedBootstrap;
 61	
 62		try {
 63			const skillContent = readFileSync(bootstrapSkillPath, "utf8");
 64			const body = stripFrontmatter(skillContent);
 65			cachedBootstrap = `${EXTREMELY_IMPORTANT_MARKER}
 66	${BOOTSTRAP_MARKER}
 67	
 68	You have superpowers.
 69	
 70	The using-superpowers skill content is included below and is already loaded for this Pi session. Follow it now. Do not try to load using-superpowers again.
 71	
 72	${body}
 73	
 74	${piToolMapping()}
 75	</EXTREMELY_IMPORTANT>`;
 76			return cachedBootstrap;
 77		} catch {
 78			cachedBootstrap = null;
 79			return null;
 80		}
 81	}
 82	
 83	function stripFrontmatter(content: string): string {
 84		const match = content.match(/^---\n[\s\S]*?\n---\n([\s\S]*)$/);
 85		return (match ? match[1] : content).trim();
 86	}
 87	
 88	function piToolMapping(): string {
 89		return `## Pi tool mapping
 90	
 91	Pi has native skills but does not expose Claude Code's \`Skill\` tool. When a Superpowers instruction says to invoke a skill, use Pi's native skill system instead: load the relevant \`SKILL.md\` with \`read\` when the skill applies, or let a human invoke \`/skill:name\` explicitly.
 92	
 93	Pi's built-in coding tools are lowercase: \`read\`, \`write\`, \`edit\`, \`bash\`, plus optional \`grep\`, \`find\`, and \`ls\`. Use those for the corresponding actions: read a file, create or edit files, run shell commands, search file contents, find files by name, and list directories.
 94	
 95	Pi does not ship a standard subagent tool. If a subagent tool such as \`subagent\` from \`pi-subagents\` is available, use it for Superpowers subagent workflows. If no subagent tool is available, do the work in this session or explain the missing capability instead of inventing \`Task\` calls.
 96	
 97	Pi does not ship a standard task-list tool. If an installed todo/task tool is available, use it. Otherwise track work in plan files or a repo-local \`TODO.md\` when task tracking is needed. Treat older \`TodoWrite\` references as this task-tracking action.`;
 98	}
 99	
100	function messageContainsBootstrap(message: unknown): boolean {
101		const content = (message as { content?: unknown }).content;
102		if (typeof content === "string") return content.includes(BOOTSTRAP_MARKER);
103		if (!Array.isArray(content)) return false;
104		return content.some((part) => {
105			return (
106				part &&
107				typeof part === "object" &&
108				(part as { type?: unknown }).type === "text" &&
109				typeof (part as { text?: unknown }).text === "string" &&
110				(part as { text: string }).text.includes(BOOTSTRAP_MARKER)
111			);
112		});
113	}
114	
115	function firstNonCompactionSummaryIndex(messages: unknown[]): number {
116		let index = 0;
117		while ((messages[index] as { role?: unknown } | undefined)?.role === "compactionSummary") {
118			index += 1;
119		}
120		return index;
121	}
  1	import assert from 'node:assert/strict';
  2	import { readFile } from 'node:fs/promises';
  3	import { existsSync } from 'node:fs';
  4	import { dirname, resolve } from 'node:path';
  5	import { fileURLToPath, pathToFileURL } from 'node:url';
  6	import test from 'node:test';
  7	
  8	const __dirname = dirname(fileURLToPath(import.meta.url));
  9	const repoRoot = resolve(__dirname, '../..');
 10	const packageJsonPath = resolve(repoRoot, 'package.json');
 11	const extensionPath = resolve(repoRoot, '.pi/extensions/superpowers.ts');
 12	const piToolsPath = resolve(repoRoot, 'skills/using-superpowers/references/pi-tools.md');
 13	
 14	async function readPackageJson() {
 15	  return JSON.parse(await readFile(packageJsonPath, 'utf8'));
 16	}
 17	
 18	async function loadExtension() {
 19	  const handlers = new Map();
 20	  const pi = {
 21	    on(event, handler) {
 22	      if (!handlers.has(event)) handlers.set(event, []);
 23	      handlers.get(event).push(handler);
 24	    },
 25	  };
 26	  const mod = await import(pathToFileURL(extensionPath).href + `?cachebust=${Date.now()}-${Math.random()}`);
 27	  mod.default(pi);
 28	  return { handlers };
 29	}
 30	
 31	function firstHandler(handlers, event) {
 32	  const eventHandlers = handlers.get(event) ?? [];
 33	  assert.equal(eventHandlers.length, 1, `expected one ${event} handler`);
 34	  return eventHandlers[0];
 35	}
 36	
 37	function textOf(message) {
 38	  if (typeof message.content === 'string') return message.content;
 39	  return message.content
 40	    .filter((part) => part.type === 'text')
 41	    .map((part) => part.text)
 42	    .join('\n');
 43	}
 44	
 45	test('package.json declares a pi package with skills and extension resources', async () => {
 46	  const pkg = await readPackageJson();
 47	
 48	  assert.equal(pkg.name, 'superpowers');
 49	  assert.ok(pkg.keywords.includes('pi-package'));
 50	  assert.deepEqual(pkg.pi.skills, ['./skills']);
 51	  assert.deepEqual(pkg.pi.extensions, ['./.pi/extensions/superpowers.ts']);
 52	});
 53	
 54	test('extension registers lifecycle hooks without pre-compaction injection', async () => {
 55	  const { handlers } = await loadExtension();
 56	
 57	  for (const event of ['resources_discover', 'session_start', 'session_compact', 'context', 'agent_end']) {
 58	    assert.equal((handlers.get(event) ?? []).length, 1, `missing ${event} handler`);
 59	  }
 60	  assert.equal((handlers.get('session_before_compact') ?? []).length, 0);
 61	});
 62	
 63	test('resources_discover contributes the bundled skills directory', async () => {
 64	  const { handlers } = await loadExtension();
 65	  const discover = firstHandler(handlers, 'resources_discover');
 66	
 67	  const result = await discover({ type: 'resources_discover', cwd: repoRoot, reason: 'startup' }, {});
 68	
 69	  assert.deepEqual(result.skillPaths, [resolve(repoRoot, 'skills')]);
 70	});
 71	
 72	test('startup context injects the bootstrap as one user message until agent_end', async () => {
 73	  const { handlers } = await loadExtension();
 74	  const sessionStart = firstHandler(handlers, 'session_start');
 75	  const context = firstHandler(handlers, 'context');
 76	  const agentEnd = firstHandler(handlers, 'agent_end');
 77	
 78	  await sessionStart({ type: 'session_start', reason: 'startup' }, {});
 79	
 80	  const originalMessages = [
 81	    { role: 'user', content: [{ type: 'text', text: 'Let us make a react todo list' }], timestamp: 1 },
 82	  ];
 83	  const result = await context({ type: 'context', messages: originalMessages }, {});
 84	
 85	  assert.equal(result.messages.length, 2);
 86	  assert.equal(result.messages[0].role, 'user');
 87	  assert.match(textOf(result.messages[0]), /You have superpowers/);
 88	  assert.match(textOf(result.messages[0]), /Pi tool mapping/);
 89	  assert.equal(result.messages[1], originalMessages[0]);
 90	
 91	  const repeatedProviderRequest = await context({ type: 'context', messages: originalMessages }, {});
 92	  assert.equal(repeatedProviderRequest.messages.length, 2);
 93	  assert.match(textOf(repeatedProviderRequest.messages[0]), /You have superpowers/);
 94	
 95	  const alreadyInjected = await context({ type: 'context', messages: result.messages }, {});
 96	  assert.equal(alreadyInjected, undefined, 'bootstrap should not duplicate when already present');
 97	
 98	  await agentEnd({ type: 'agent_end', messages: [] }, {});
 99	  const afterEnd = await context({ type: 'context', messages: originalMessages }, {});
100	  assert.equal(afterEnd, undefined, 'startup bootstrap should clear after agent_end');
101	});
102	
103	test('session_compact injects bootstrap after compaction summaries, not before compaction', async () => {
104	  const { handlers } = await loadExtension();
105	  const sessionCompact = firstHandler(handlers, 'session_compact');
